class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        M = max(nums)
        occ = []
        total = 0
        for r, x in enumerate(nums):
            if x == M:
                occ.append(r)
            if len(occ) >= k:
                total += occ[len(occ) - k] + 1
        return total
